  "bestCut.replace": "Применение заменит таймлайн проекта. Отмена восстановит предыдущий.",
  "bestCut.consent": "Чтобы выбрать лучший дубль, выбранные видеофайлы целиком загружаются в Veyrnox.ai и передаются сервису расшифровки речи для чтения аудио. Сценарий и заметки остаются на телефоне. Удаление временных загрузок запланировано через 24 часа; очистка может занять больше времени. Расшифровки хранятся до 30 дней, чтобы не взимать плату повторно. Удаление аккаунта удаляет расшифровки. Оригиналы библиотеки и резервные копии проектов имеют собственные сроки хранения. Если никто не говорит, плата не взимается.",
