  "helpGuides.content.first-generation.s1.title": "Откройте студию",
  "helpGuides.content.first-generation.s2.body": "В списке справа показаны все модели с ценой в кредитах. Модели для изображений, видео и аудио тратят кредиты с одного баланса.",
