  "helpGuides.content.templates.s3.body": "Кнопка «Использовать шаблон» откроет студию с готовыми промптом, моделью и соотношением сторон. Пока вы не нажмёте «Создать», списаний не будет.",
  "helpGuides.content.templates.s3.title": "Использовать",
